let storage;try{storage=window.localStorage;}catch{}
const damage=new DamageLedger(storage),progress=new Progression(storage),audio=new EngineAudio(),keyboard=new FlightKeyboard(),keys=keyboard.keys,instruments=new InstrumentSmoother(),touch={pitch:0,roll:0,yaw:0,boost:false};
let renderBudget,fpsClock=0;
