const locked=()=>loading||mode==='crash'||mode==='landing';
const money=v=>'$'+Math.floor(v).toLocaleString();
function toast(text){if(locked())return;$('toast').textContent=text;$('toast').style.opacity='1';toastTimer=3;}
function clearInput(){keyboard.clear();touch.pitch=touch.roll=touch.yaw=0;touch.boost=false;$('stick').style.transform='';}
function loadingUI(text){$('loading').style.display='flex';$('loadText').textContent=text;}
async function prepareWorld(seed,p,velocity=null){world.reset(seed);world.update(p,true,velocity);while(world.loading){$('loadText').textContent='Charting new terrain… '+Math.round(world.chunks.size/Math.max(1,world.desired.size)*100)+'%';await new Promise(r=>setTimeout(r,4));world.update(p,true,velocity);}}

function buildPlane(){if(plane&&!plane.root.isDisposed())plane.root.dispose(false,false);plane=createAircraft(scene,selected);attachUpgrades();addShadows();setPlaneInfo();}
function attachUpgrades(){installEquipment(plane,progress);prepareRotors(plane);}
function addShadows(){shadow.getShadowMap().renderList=[];for(const mesh of glowing)glow.removeIncludedOnlyMesh(mesh);glowing=[];for(const p of plane.parts){if(!p.mesh.metadata?.rotorBlade)shadow.addShadowCaster(p.mesh);if(p.mesh.material?.name.startsWith('radiant ')){glow.addIncludedOnlyMesh(p.mesh);glowing.push(p.mesh);}}glow.isEnabled=glowing.length>0;}
function setPlaneInfo(){if(!plane)return;$('planeTitle').textContent=plane.spec.name;$('planeDescription').innerHTML=plane.spec.description;$('voxelCount').textContent=plane.voxelCount.toLocaleString();$('partCount').textContent=plane.partCount;$('ratedSpeed').textContent='M '+progress.spec(selected).maxMach.toFixed(2);for(const c of document.querySelectorAll('[data-plane]')){c.classList.toggle('selected',c.dataset.plane===selected);c.setAttribute('aria-pressed',String(c.dataset.plane===selected));}updateBank();}
function updateOwnershipUI(){const owned=progress.owns(selected),price=AIRCRAFT_PRICE[selected];$('flyButton').innerHTML=owned?'START RUN <span>↗</span>':'BUY AIRCRAFT · '+money(price)+' <span>↗</span>';$('flyButton').disabled=!owned&&progress.data.bank<price;for(const type of AIRCRAFT_TYPES){const card=document.querySelector('[data-plane="'+type+'"]');card.classList.toggle('aircraft-locked',!progress.owns(type));card.querySelector('small').textContent=progress.owns(type)?AIRCRAFT_TAGS[type]:'LOCKED · '+money(AIRCRAFT_PRICE[type]);}}
function updateBank(){$('bankValue').textContent=money(progress.data.bank);$('bestDistance').textContent=(progress.data.best/1000).toFixed(2)+' KM';updateOwnershipUI();}
function launchSelected(){if(locked())return;if(progress.owns(selected)){startRun();return;}if(progress.purchaseAircraft(selected)){updateBank();toast(SPECS[selected].name+' purchased. Ready for your first flight.');}}
function grantChordCredit(){progress.addBank(10000);updateBank();if($('shop').open)renderShop();if($('blackMarket').open)renderMarket();}
async function selectPlane(type){if(locked()||mode!=='hangar'||type===selected)return;loading=true;$('buildStatus').textContent='ASSEMBLING AIRCRAFT…';await new Promise(r=>setTimeout(r,20));selected=type;buildPlane();plane.root.position.set(0,groundHeight(0,0)+plane.spec.gearHeight,0);orbitDistance=type==='prop'?19:type==='jet'?21:24;effects.clear();$('buildStatus').textContent='BALANCED FLIGHT · UPDATE 8';loading=false;}
async function startRun(){if(locked())return;if(!progress.owns(selected)){toast('Purchase this aircraft before starting a run.');return;}loading=true;paused=false;clearInput();$('resultsOverlay').hidden=true;$('pauseOverlay').hidden=true;$('shop').close();$('blackMarket').close();sonic.clear();weapons.clear();pickups?.clear();pickupMarkers?.clear();loadingUI('Preparing your next flight…');crash.clear();effects.clear();traffic.reset(WORLD_SEED);const seed=WORLD_SEED;await prepareWorld(seed,V.Zero(),new V(0,0,$('startMode').value==='air'?progress.spec(selected).cruise:0));buildPlane();flight=new Flight(selected,$('startMode').value,progress.spec(selected));run=new Run();weapons.reset(plane,activeModule(progress,selected,'weapons')?.weapon);padEdges.clear();pickups.reset();mode='flight';instruments.reset();markers?.clear();cameraAim=null;visibleWarning=warningCandidate='';warningAge=0;emptyNotified=false;cameraMode=0;lookYaw=lookPitch=0;accumulator=0;plane.root.position.copyFrom(flight.position);plane.root.rotationQuaternion.copyFrom(flight.q);$('hangar').hidden=true;$('flightUI').hidden=false;$('shopButton').hidden=true;$('modeLabel').textContent='LIVE RUN';updateButtons();updateCamera(.016,true);loading=false;$('loading').style.display='none';updateHUD(1);toast(flight.ground?'Shift adds power. Pull back with S to take off.':'Fly north. Keep your airspeed up. Watch for traffic.');}
async function showHangar(){if(locked())return;loading=true;$('shop').close();$('blackMarket').close();sonic.clear();weapons.clear();pickups?.clear();pickupMarkers?.clear();mode='hangar';cameraAim=null;markers?.clear();paused=false;clearInput();$('resultsOverlay').hidden=true;$('pauseOverlay').hidden=true;$('flightUI').hidden=true;$('shopButton').hidden=false;loadingUI('Returning to the airfield…');crash.clear();effects.clear();traffic.reset(1);await prepareWorld(18273,V.Zero());buildPlane();plane.root.position.set(0,groundHeight(0,0)+plane.spec.gearHeight,0);$('hangar').hidden=false;$('modeLabel').textContent='HANGAR';loading=false;updateDamageUI();updateCamera(.016,true);$('loading').style.display='none';}
function pause(toggle=!paused){if(mode!=='flight'||locked())return;paused=toggle;clearInput();$('pauseOverlay').hidden=!paused;$('modeLabel').textContent=paused?'PAUSED':'LIVE RUN';}
function endRun(outcome){if(!run||run.ended)return;run.end(outcome,progress);paused=false;clearInput();mode=outcome==='crashed'?'crash':'landing';$('toast').style.opacity='0';toastTimer=0;sonic.clear();weapons.stopProjectiles();pickupMarkers?.clear();if(outcome==='crashed'){crash.start(plane,flight.velocity,flight.impact,flight.fuel);}audio.impact?.(outcome==='crashed');}
function showResults(){if(run.outcome==='landed')stopRotors(plane);if(run.outcome==='crashed'){const g=world.globalPosition(crash.center);damage.addWreck(g.x,g.z,selected);}mode='results';const r=run.result;$('flightUI').hidden=true;$('pauseOverlay').hidden=true;$('resultsOverlay').hidden=false;$('shopButton').hidden=false;$('modeLabel').textContent=r.outcome==='landed'?'SAFE LANDING':'RUN COMPLETE';$('resultLabel').textContent=r.outcome==='landed'?'TOUCHDOWN':'AIRCRAFT LOST';$('resultTitle').textContent=r.outcome==='landed'?'Brought it home.':'A spectacular exit.';$('resultReason').textContent=r.outcome==='landed'?'A controlled landing. Your earnings are banked.':flight.crashReason;$('resultDistance').textContent=(r.distance/1000).toFixed(2);$('newBest').hidden=!r.best;$('distanceReward').textContent=money(r.base);$('nearReward').textContent=money(r.near);$('lowReward').textContent=money(r.low||0);$('combatReward').textContent=money(r.combat||0);$('landingReward').textContent=money(r.landing);$('totalReward').textContent=money(r.earned);updateBank();updateDamageUI();if(progress.saveFailed||damage.failed)toast('Progress is available this session; device storage is unavailable.');}
function gear(){if(mode!=='flight'||paused||locked())return;if(flight.ground){toast('Keep the gear down on the runway.');return;}flight.gear=1-flight.gear;updateButtons();}
function flaps(){if(mode!=='flight'||paused||locked())return;flight.flaps=flight.flaps===0?.5:flight.flaps===.5?1:0;updateButtons();}
function cycleCamera(){if(mode!=='flight'||locked())return;cameraMode=(cameraMode+1)%3;lookYaw=lookPitch=0;updateButtons();}
function updateButtons(){if(!flight)return;$('gearButton').innerHTML=(flight.gear?'GEAR DOWN':'GEAR UP')+' <kbd>G</kbd>';$('flapsButton').innerHTML=`FLAPS ${Math.round(flight.flaps*30)}° <kbd>F</kbd>`;$('assistButton').textContent='ASSIST '+(flight.assist?'ON':'OFF');$('assistButton').classList.toggle('active',flight.assist);$('throttle').value=flight.throttle*100;$('cameraButton').innerHTML=cameraNames[cameraMode]+' <kbd>C</kbd>';}
function refreshModels(){updateBank();if(mode==='hangar'){const pos=plane.root.position.clone();buildPlane();plane.root.position.copyFrom(pos);}updateDamageUI();}
function updateDamageUI(){const count=damage.count;for(const id of['repairDamage','repairResults']){$(id).disabled=!count;$(id).textContent=count?'REPAIR ENVIRONMENT · FREE':'ENVIRONMENT REPAIRED';}$('damageStatus').textContent=count?count+' saved damage records · runways restore each run':'Persistent world · runway surfaces restore each run';$('retryButton').disabled=false;$('retryButton').innerHTML='FLY AGAIN <span>↗</span>';}
async function repairDamage(){if(locked()||mode==='flight')return;damage.repair();await showHangar();updateDamageUI();toast('Terrain, obstacles and wreckage reset. Aircraft repair automatically.');}
function openShop(){if(locked()||mode==='flight')return;$('blackMarket').close();shopPlane=selected;shopSelection='fuel';shopLevelSelection=null;$('shop').showModal();renderShop();}
function openMarket(){if(locked()||mode==='flight')return;$('shop').close();shopPlane=selected;marketSelection=MODULES[shopPlane][0].id;$('blackMarket').showModal();renderMarket();}
function comparePerformance(choice){const current=progress.spec(shopPlane),next=progress.spec(shopPlane,choice),endurance=s=>s.fuelCapacity/((s.fuelIdle+s.fuelRate)*s.fuelEfficiency*s.fuelBurnMultiplier);return 'Rated speed M '+current.maxMach.toFixed(3)+' → '+next.maxMach.toFixed(3)+' · Full-power fuel '+Math.round(endurance(current))+' → '+Math.round(endurance(next))+' sec'+((next.afterburner??shopPlane==='jet')?' (boost off)':'');}
function renderShop(){
 $('shopBank').textContent=money(progress.data.bank);const owned=progress.owns(shopPlane),price=AIRCRAFT_PRICE[shopPlane];$('aircraftPurchase').hidden=owned;$('purchaseTitle').textContent=SPECS[shopPlane].name;$('purchaseAircraft').textContent='BUY AIRCRAFT · '+money(price);$('purchaseAircraft').disabled=progress.data.bank<price;
 for(const b of document.querySelectorAll('[data-shop-plane]'))b.classList.toggle('selected',b.dataset.shopPlane===shopPlane);
 const grid=$('upgradeGrid');grid.replaceChildren();for(const u of UPGRADES){const lvl=progress.level(shopPlane,u.id),card=document.createElement('button');card.className='upgrade-card inspect-card';card.classList.toggle('selected',shopSelection===u.id);card.setAttribute('aria-pressed',String(shopSelection===u.id));card.innerHTML='<span class="upgrade-number">'+u.icon+' / '+(lvl?'OWNED THROUGH MK '+lvl:'STOCK')+'</span><strong>'+u.name+'</strong><span>'+u.description+'</span><b>'+(lvl>=5?'ALL LEVELS OWNED':money(progress.cost(shopPlane,u.id))+' NEXT')+' <i>INSPECT 3D ↗</i></b>';card.onclick=()=>{shopSelection=u.id;shopLevelSelection=null;renderShop();};grid.append(card);}
 const u=UPGRADES.find(v=>v.id===shopSelection),highest=progress.level(shopPlane,u.id),cost=progress.cost(shopPlane,u.id);if(shopLevelSelection===null||shopLevelSelection>Math.min(5,highest+1))shopLevelSelection=Math.min(5,highest+1);const lvl=shopLevelSelection,purchased=lvl<=highest,installed=!activeModule(progress,shopPlane,u.id)&&progress.installedLevel(shopPlane,u.id)===lvl,choice={slot:u.id,level:lvl,module:null};
 const levels=$('ownedLevels');levels.replaceChildren();for(let n=0;n<=Math.min(5,highest+1);n++){const b=document.createElement('button');b.textContent=(n?'MK '+n:'STOCK')+(n>highest?' · BUY':'');b.classList.toggle('selected',n===lvl);b.setAttribute('aria-pressed',String(n===lvl));b.onclick=()=>{shopLevelSelection=n;renderShop();};levels.append(b);}
 shopPreview??=new PartPreview($('partPreview'));shopPreview.show(shopPlane,choice);$('previewPerformance').textContent=comparePerformance(choice);$('previewName').textContent=u.name+' · '+(lvl?'Mk '+lvl:'Stock');$('previewDetails').textContent=(purchased?'Owned assembly. Reinstall for free at any time. ':'Workshop hardware for this slot. ')+u.description+'.'+(activeModule(progress,shopPlane,u.id)?' Installing this removes the black-market part from this slot; it remains owned.':'');$('previewCount').textContent=shopPreview.kit.parts.reduce((n,p)=>n+p.count,0).toLocaleString()+' VOXELS · '+shopPreview.kit.parts.length+' PARTS';
 const buy=$('buyUpgrade');buy.textContent=!owned?'PURCHASE AIRCRAFT FIRST':installed?'CURRENTLY INSTALLED':purchased?'EQUIP OWNED ASSEMBLY':money(cost)+' · BUY & INSTALL';buy.disabled=!owned||installed||!purchased&&progress.data.bank<cost;buy.onclick=()=>{if(purchased?progress.equipLevel(shopPlane,u.id,lvl):progress.buy(shopPlane,u.id)){renderShop();refreshModels();toast(u.name+' '+(lvl?'Mk '+lvl:'stock')+' installed.');}};$('saveStatus').textContent=progress.saveFailed?'Device storage unavailable. Progress lasts for this session.':'Every purchased level stays owned. Select Stock or any Mk above to inspect and equip it.';
}
function renderMarket(){
 $('marketBank').textContent=money(progress.data.bank);for(const b of document.querySelectorAll('[data-market-plane]'))b.classList.toggle('selected',b.dataset.marketPlane===shopPlane);
 if(!MODULES[shopPlane].some(m=>m.id===marketSelection))marketSelection=MODULES[shopPlane][0].id;$('marketFaction').textContent=({prop:'SUNBIRD DIVISION / EMERALD FUSION',swift:'TEMPEST DIVISION / AMBER ARC TURBINES',jet:'WRAITH DIVISION / VIOLET REACTORS',ufo:'PARADOX DIVISION / ALIEN PHASE TECHNOLOGY'})[shopPlane];$('blackMarket').dataset.aircraft=shopPlane;
 const grid=$('marketGrid');grid.replaceChildren();for(const m of MODULES[shopPlane]){const owned=progress.data.modules[shopPlane][m.id],equipped=activeModule(progress,shopPlane,m.slot)===m,card=document.createElement('button');card.className='market-card';card.classList.toggle('selected',marketSelection===m.id);card.setAttribute('aria-pressed',String(marketSelection===m.id));card.innerHTML='<span>'+m.tag+'</span><strong>'+m.name+'</strong><small>'+m.stats+'</small><b>'+(equipped?'INSTALLED':owned?'OWNED · SWAP ANYTIME':money(m.price))+' <i>INSPECT ↗</i></b>';card.onclick=()=>{marketSelection=m.id;renderMarket();};grid.append(card);}
 const m=moduleFor(shopPlane,marketSelection),owned=progress.data.modules[shopPlane][m.id],equipped=activeModule(progress,shopPlane,m.slot)===m,aircraftOwned=progress.owns(shopPlane);marketPreview??=new PartPreview($('marketPreview'));marketPreview.show(shopPlane,{slot:m.slot,level:5,module:m});$('marketPartName').textContent=m.name;$('marketDescription').textContent=m.description;$('marketStats').textContent=m.stats;$('marketPerformance').textContent=comparePerformance({slot:m.slot,level:5,module:m});$('marketCount').textContent=marketPreview.kit.parts.reduce((n,p)=>n+p.count,0).toLocaleString()+' VOXELS · LIVE ASSEMBLY';const buy=$('buyModule');buy.textContent=!aircraftOwned?'PURCHASE AIRCRAFT IN WORKSHOP':equipped?'REMOVE · USE WORKSHOP PART':owned?'INSTALL OWNED MODULE':money(m.price)+' · ACQUIRE & INSTALL';buy.disabled=!aircraftOwned||!owned&&progress.data.bank<m.price;buy.onclick=()=>{const changed=owned?progress.equipModule(shopPlane,m.id):progress.buyModule(shopPlane,m.id);if(changed){renderMarket();refreshModels();toast(equipped?'Workshop hardware restored.':m.name+' installed.');}};
}
function lockTarget(){if(mode!=='flight'||paused||locked())return;if(!weapons.weapon){toast('Purchase a missile system in the black market.');return;}const previous=weapons.target,acquired=weapons.selectTarget(flight);toast(acquired?'Acquiring target. Keep it ahead and in sight.':previous?'Lock cleared. Missiles will fire straight.':'No visible target ahead.');}
function fireMissile(){if(mode!=='flight'||paused||locked())return;if(!weapons.weapon){toast('Purchase a missile system in the black market.');return;}if(!weapons.fire(flight)&&!weapons.ammo)toast('Missiles depleted. Fly through a cyan reload beacon to refill.');updateWeaponUI();}
function updateWeaponUI(){const enabled=!!weapons.weapon;$('weaponPanel').hidden=!enabled;$('lockReticle').hidden=true;if(!enabled)return;put('missileAmmo',weapons.ammo+' / '+weapons.weapon.ammo);put('seekerState',weapons.locked?'TARGET LOCKED':weapons.target?'ACQUIRING '+Math.round(weapons.lockProgress*100)+'%':'UNGUIDED · AIM AIRCRAFT NOSE');put('weaponTarget',weapons.target?.def.name||'T selects / cycles moving targets');$('fireMissile').disabled=!weapons.ammo||weapons.cooldown>0;$('fireMissile').classList.toggle('guided',weapons.locked);const label=weapons.locked?'FIRE GUIDED':'FIRE STRAIGHT';if($('fireMissile').dataset.label!==label){$('fireMissile').dataset.label=label;$('fireMissile').innerHTML=label+' <kbd>X</kbd>';}$('lockButton').classList.toggle('active',weapons.locked);const e=markers.entries.get(weapons.target);if(e&&!e.node.classList.contains('edge')){$('lockReticle').hidden=false;$('lockReticle').style.transform=`translate3d(${e.x}px,${e.y}px,0)`;$('lockReticle').classList.toggle('locked',weapons.locked);$('lockReticle').style.setProperty('--lock-progress',weapons.lockProgress);}}
async function resetProgress(){if(locked()||mode!=='hangar')return;$('resetDialog').close();progress.reset();damage.repair();run=null;flight=null;selected=shopPlane='prop';shopSelection='fuel';marketSelection='sunbird';$('startMode').value='air';instruments.reset();clearInput();audio.enabled=false;$('soundButton').textContent='SOUND OFF';weapons.clear();await showHangar();updateBank();updateDamageUI();toast('New game started. All game progress and world damage reset.');}
function bindControls(){$('lockButton').onclick=lockTarget;$('fireMissile').onclick=fireMissile;$('resetProgress').onclick=()=>{if(!locked()&&mode==='hangar')$('resetDialog').showModal();};$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=resetProgress;for(const b of document.querySelectorAll('[data-market-plane]'))b.onclick=()=>{shopPlane=b.dataset.marketPlane;marketSelection=MODULES[shopPlane][0].id;renderMarket();};for(const id of['blackMarketButton','workshopMarket','resultsMarket'])$(id).onclick=openMarket;$('closeMarket').onclick=()=>$('blackMarket').close();$('marketWorkshop').onclick=openShop;$('repairDamage').onclick=repairDamage;$('repairResults').onclick=repairDamage;for(const b of document.querySelectorAll('[data-plane]'))b.onclick=()=>selectPlane(b.dataset.plane);for(const b of document.querySelectorAll('[data-shop-plane]'))b.onclick=()=>{shopPlane=b.dataset.shopPlane;shopLevelSelection=null;renderShop();};$('flyButton').onclick=launchSelected;$('purchaseAircraft').onclick=()=>{if(progress.purchaseAircraft(shopPlane)){updateBank();renderShop();toast(SPECS[shopPlane].name+' purchased.');}};$('retryButton').onclick=startRun;$('resultsHangar').onclick=showHangar;$('resultsShop').onclick=openShop;$('modelShop').onclick=openShop;$('shopButton').onclick=openShop;$('closeShop').onclick=()=>$('shop').close();$('pauseButton').onclick=()=>pause();$('resumeButton').onclick=()=>pause(false);$('abandonButton').onclick=showHangar;$('cameraButton').onclick=cycleCamera;$('gearButton').onclick=gear;$('flapsButton').onclick=flaps;$('assistButton').onclick=()=>{if(mode!=='flight'||locked())return;flight.assist=!flight.assist;updateButtons();};$('throttle').oninput=e=>{if(mode==='flight'&&!locked())flight.throttle=+e.target.value/100;};$('soundButton').onclick=async()=>{if(locked())return;try{$('soundButton').textContent=await audio.toggle()?'SOUND ON':'SOUND OFF';}catch{toast('Audio is unavailable in this browser.');}};
 let helpPaused=false;$('helpButton').onclick=()=>{if(locked())return;helpPaused=mode==='flight'&&!paused;if(helpPaused)pause(true);$('help').showModal();};$('closeHelp').onclick=()=>$('help').close();$('help').addEventListener('close',()=>{if(helpPaused)pause(false);helpPaused=false;});document.querySelector('.brand').onclick=e=>{e.preventDefault();if(locked())return;if(mode==='flight')pause(true);else if(mode==='results')showHangar();};
 document.addEventListener('keydown',e=>{const editing=e.target.tagName==='SELECT'||e.target.tagName==='TEXTAREA'||e.target.tagName==='INPUT'&&e.target.type!=='range';const eligible=(mode==='hangar'||mode==='flight')&&!locked()&&!editing;if(keyboard.down(e.code,eligible))grantChordCredit();if(mode==='flight'&&['AltLeft','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(editing||$('help').open||$('shop').open||$('blackMarket').open||$('resetDialog').open||locked()||e.repeat||mode!=='flight')return;if(['KeyP','Escape','KeyR'].includes(e.code))pause();else if(e.code==='KeyC')cycleCamera();else if(e.code==='KeyG')gear();else if(e.code==='KeyF')flaps();else if(e.code==='KeyT'){e.preventDefault();lockTarget();}else if(e.code==='KeyX'){e.preventDefault();fireMissile();}});document.addEventListener('keyup',e=>{keyboard.up(e.code);if(e.code==='AltLeft'&&mode==='flight')e.preventDefault();});window.addEventListener('blur',()=>{background=true;clearInput();if(mode==='flight')pause(true);});window.addEventListener('focus',()=>background=false);document.addEventListener('visibilitychange',()=>{background=document.hidden;if(background){clearInput();if(mode==='flight')pause(true);}});
 const canvas=$('world');canvas.addEventListener('pointerdown',e=>{if(locked())return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId||locked())return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(mode==='hangar'){orbitAngle-=dx*.007;orbitElev=clamp(orbitElev+dy*.004,.04,1.1);}else{lookYaw-=dx*.005;lookPitch=clamp(lookPitch+dy*.004,-.9,.9);}});for(const name of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();if(mode==='hangar'&&!locked())orbitDistance=clamp(orbitDistance+e.deltaY*.012,10,35);},{passive:false});
 const joy=$('joystick');let joyId=null;const setJoy=e=>{const r=joy.getBoundingClientRect(),x=clamp((e.clientX-r.left-r.width/2)/(r.width*.4),-1,1),y=clamp((e.clientY-r.top-r.height/2)/(r.height*.4),-1,1);touch.roll=x;touch.pitch=-y;$('stick').style.transform=`translate(${x*r.width*.3}px,${y*r.height*.3}px)`;};joy.onpointerdown=e=>{if(locked())return;joyId=e.pointerId;joy.setPointerCapture(e.pointerId);setJoy(e);};joy.onpointermove=e=>{if(joyId===e.pointerId&&!locked())setJoy(e);};const release=()=>{joyId=null;touch.pitch=touch.roll=0;$('stick').style.transform='';};joy.onpointerup=release;joy.onpointercancel=release;joy.onlostpointercapture=release;
 for(const[id,value]of[['rudderLeft',-1],['rudderRight',1],['boostTouch',true]]){const el=$(id),field=id==='boostTouch'?'boost':'yaw';el.onpointerdown=e=>{if(locked())return;el.setPointerCapture(e.pointerId);touch[field]=value;};for(const name of['onpointerup','onpointercancel','onlostpointercapture'])el[name]=()=>touch[field]=id==='boostTouch'?false:0;}
}
function getInput(dt){const is=k=>keys.has(k)?1:0;const input={pitch:is('KeyW')+is('ArrowUp')-is('KeyS')-is('ArrowDown')+touch.pitch,roll:is('KeyD')+is('ArrowRight')-is('KeyA')-is('ArrowLeft')+touch.roll,yaw:is('KeyE')-is('KeyQ')+touch.yaw,throttle:keyboard.throttle(),boost:keys.has('Space')||touch.boost,brake:keys.has('Space')||touch.boost};const pad=Array.from(navigator.getGamepads?.()||[]).find(g=>g&&g.connected);const edges=padEdges.poll(pad);if(edges.fire)fireMissile();if(edges.lock)lockTarget();if(edges.gear)gear();if(edges.flaps)flaps();if(pad){const dz=v=>Math.abs(v)>.12?v:0;input.roll+=dz(pad.axes[0]||0);input.pitch-=dz(pad.axes[1]||0);input.yaw+=(pad.buttons[5]?.value||0)-(pad.buttons[4]?.value||0);input.throttle+=(pad.buttons[7]?.value||0)-(pad.buttons[6]?.value||0);input.boost||=pad.buttons[0]?.pressed;input.brake||=pad.buttons[1]?.pressed;lookYaw-=dz(pad.axes[2]||0)*1.32*dt;lookPitch=clamp(lookPitch+dz(pad.axes[3]||0)*.96*dt,-.9,.9);}for(const k of['pitch','roll','yaw','throttle'])input[k]=clamp(input[k],-1,1);return input;}
function updateCamera(dt,snap=false){let dest,target,desiredFov=camera.fov;camera.upVector.copyFromFloats(0,1,0);if(mode==='crash'||mode==='results'&&run?.outcome==='crashed'){const t=crash.time,center=crash.center,a=Math.atan2(flight.velocity.x,flight.velocity.z)+2.3+Math.min(t,4)*.18;const distance=Math.max(32,Math.min(220,crash.radius*2.5));dest=center.add(new V(Math.sin(a)*distance,Math.max(15,crash.radius*.9),Math.cos(a)*distance));target=center.clone();desiredFov=.88;}
 else{const pos=plane.root.position;const cockpitView=mode==='flight'&&cameraMode===1;for(const p of plane.parts)if(p.name==='cockpit glass and framing')p.mesh.isVisible=!cockpitView;
  if(mode==='hangar'){orbitAngle+=drag?0:dt*.023;dest=pos.add(new V(Math.sin(orbitAngle)*orbitDistance,4.2+orbitElev*orbitDistance,Math.cos(orbitAngle)*orbitDistance));target=pos.add(new V(-1.5,.4,0));desiredFov=.69;if(window.innerWidth<800){dest=pos.add(new V(Math.sin(orbitAngle)*(orbitDistance+4),6+orbitElev*orbitDistance,Math.cos(orbitAngle)*(orbitDistance+4)));target=pos.add(new V(0,-.9,0));}}
  else{const{f,u,r}=flight.axes(),heading=Math.atan2(f.x,f.z),a=heading+Math.PI+lookYaw;if(cameraMode===1&&mode==='flight'){const local=new V(...(flight.spec.cockpit||[0,1.34,selected==='jet'?2.16:1.14])),m=B.Matrix.FromQuaternionToRef(flight.q,new B.Matrix());dest=pos.add(V.TransformNormal(local,m));target=dest.add(f.scale(Math.cos(lookYaw)*Math.cos(lookPitch)*50)).add(r.scale(-Math.sin(lookYaw)*50)).add(u.scale(-Math.sin(lookPitch)*50));camera.upVector.copyFrom(u);desiredFov=.98;}
   else if(cameraMode===2&&mode==='flight'){const oa=time*.12+lookYaw;dest=pos.add(new V(Math.sin(oa)*21,6+lookPitch*12,Math.cos(oa)*21));target=pos.clone();desiredFov=.76;}
   else{dest=pos.add(new V(Math.sin(a)*20,5.8+lookPitch*9,Math.cos(a)*20));target=pos.add(f.scale(10)).add(new V(0,1,0));desiredFov=.81+clamp(flight.speed/350,0,.15);}}
 }
 camera.minZ=mode==='flight'&&cameraMode===1?.12:1;dest.y=Math.max(dest.y,Math.max(0,groundHeight(dest.x,dest.z))+1.15);if(snap||cameraMode===1&&mode==='flight')camera.position.copyFrom(dest);else camera.position=V.Lerp(camera.position,dest,1-Math.exp(-dt*(mode==='crash'?2.5:4)));if(snap||!cameraAim||cameraMode===1&&mode==='flight')cameraAim=target.clone();else cameraAim=V.Lerp(cameraAim,target,1-Math.exp(-dt*10));camera.fov=snap?desiredFov:camera.fov+(desiredFov-camera.fov)*(1-Math.exp(-dt*8));camera.setTarget(cameraAim);sun.position.copyFrom(target.add(new V(32,65,-28)));
}
function put(id,value){const el=$(id),text=String(value);if(el.textContent!==text)el.textContent=text;}
function updateHUD(dt){const t=flight.telemetry(),pct=flight.fuel/flight.fuelCapacity*100,sample=(key,value,response=9,wrap=0)=>instruments.sample(key,value,dt,response,wrap);
 put('distanceValue',(sample('distance',run.distance,12)/1000).toFixed(2));put('runMoney',money(run.flightEarnings));put('dodgedValue',run.dodged+' DODGED'+(run.hits?' · '+run.hits+' HITS':''));put('biomeName',world.biome(flight.position));put('lowFlightValue',money(run.lowCredits));put('lowFlightRate','+$'+run.lowRate.toFixed(1)+'/SEC');$('lowFlightBonus').classList.toggle('earning',run.lowRate>0);$('lowFlightMeter').style.transform=`scaleX(${clamp(sample('lowRate',run.lowRate,8)/REWARDS.lowMaxPerSecond,0,1)})`;
 put('machValue','MACH '+(sample('mach',flight.speed/soundSpeed(flight.position.y),8)).toFixed(2));$('machValue').classList.toggle('supersonic',flight.speed>=soundSpeed(flight.position.y));put('speed',Math.round(sample('speed',t.knots)));put('altitude',Math.round(sample('altitude',t.altitude)).toLocaleString());put('heading',String(Math.round(sample('heading',t.heading,12,360))%360).padStart(3,'0'));const vs=sample('verticalSpeed',t.verticalSpeed,6);put('verticalSpeed',(vs>=0?'+':'')+Math.round(vs/10)*10+' FT/MIN');put('throttleValue',Math.round(flight.throttle*100));if(document.activeElement!==$('throttle'))$('throttle').value=flight.throttle*100;
 const pitch=sample('pitch',t.pitch,12),bank=sample('bank',t.bank,12,Math.PI*2);$('attitudeDisk').style.transform=`rotate(${-bank*180/Math.PI}deg) translateY(${clamp(pitch*35,-30,30)}px)`;put('fuelValue',Math.ceil(pct)+'%');$('fuelBar').style.transform=`scaleX(${clamp(sample('fuel',pct,10)/100,0,1)})`;$('fuelBar').classList.toggle('low',pct<20);
 put('fuelNote',flight.fuel<=0?'ENGINE OUT · GLIDING':flight.engine<-.02?'REVERSE THRUST':flight.throttle<0?'REVERSER DEPLOYING':flight.boost?'AFTERBURNER · HIGH BURN':flight.throttle>.8?'HIGH POWER':'ECONOMY CRUISE');let warning='';if(flight.fuel<=0)warning='ENGINE OUT · GLIDE TO A LANDING';else if(flight.engine<-.02)warning='REVERSE THRUST · WATCH AIRSPEED';else if(flight.stall>.2&&!flight.ground)warning='STALL · LOWER THE NOSE';else if(!flight.ground&&flight.terrainAheadClearance()<0)warning='TERRAIN AHEAD · CLIMB';else if(t.agl<120&&!flight.ground)warning=flight.gear?'LOW TERRAIN CLEARANCE': 'LOW TERRAIN CLEARANCE · LOWER GEAR';else if(!flight.ground&&flight.terrainAheadClearance()<30)warning='RISING TERRAIN · CLIMB';else if(pct<20)warning='FUEL LOW · FIND A LANDING';else if(t.heading>70&&t.heading<290)warning='FLY NORTH TO GAIN DISTANCE';else if(flight.ground&&flight.speed<8)warning='RUNWAY · SHIFT TO ADD POWER';
 if(warning!==warningCandidate){warningCandidate=warning;warningAge=0;}else warningAge+=dt;if(warningAge>.18||flight.fuel<=0){visibleWarning=warningCandidate;put('flightWarning',visibleWarning);$('flightWarning').style.opacity=visibleWarning?'1':'0';}
 camera.getViewMatrix(true);scene.updateTransformMatrix(true);const contacts=markers.update(traffic.items,flight,camera,scene,engine,dt,innerWidth,innerHeight,weapons);pickupMarkers.update(pickups.items,flight,camera,scene,engine,dt,innerWidth,innerHeight);updateWeaponUI();put('trafficWarning',contacts.count?contacts.count+' AIR CONTACT'+(contacts.count===1?'':'S')+' · CLOSEST '+Math.round(contacts.closest)+' M':'');
}
function rebase(){if(Math.abs(flight.position.x)<7680&&Math.abs(flight.position.z)<7680)return;const dx=Math.trunc(flight.position.x/(CHUNK*8))*(CHUNK*8),dz=Math.trunc(flight.position.z/(CHUNK*8))*(CHUNK*8);world.rebase(dx,dz);flight.position.x-=dx;flight.position.z-=dz;plane.root.position.x-=dx;plane.root.position.z-=dz;camera.position.x-=dx;camera.position.z-=dz;if(cameraAim){cameraAim.x-=dx;cameraAim.z-=dz;}traffic.rebase(dx,dz);sonic.rebase(dx,dz);weapons.rebase(dx,dz);pickups.rebase(dx,dz);for(const p of effects.items){p.mesh.position.x-=dx;p.mesh.position.z-=dz;}}
function render(){if(!scene||loading||background){renderBudget?.reset();if(flight)audio.update({throttle:0},selected,true);return;}const rawDt=engine.getDeltaTime()/1000,dt=Math.min(rawDt,.085);fpsClock+=rawDt;renderBudget.sample(rawDt);if(fpsClock>=1){put('fpsReadout',(renderBudget.fps??'—')+' FPS');fpsClock=0;}if(renderBudget.changed)renderBudget.apply(engine,shadow);if(!paused)time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').style.opacity='0';}
 if($('shop').open||$('blackMarket').open){audio.update({throttle:0},selected,true);shopPreview?.render(rawDt);marketPreview?.render(rawDt);return;}
 if(mode==='hangar'){const state={pitch:Math.sin(time*.6)*.35,roll:Math.sin(time*.45)*.45,yaw:Math.sin(time*.5)*.35,flaps:0,gear:1,speed:0,ground:true,throttle:.16};animateAircraft(plane,dt,state);effects.exhaust(plane,state,dt);audio.update(state,selected,false);}
 else if(mode==='flight'&&!paused){const input=getInput(dt),previous=flight.position.clone();accumulator+=dt;let steps=0;while(accumulator>=1/120&&steps<12&&!flight.crashed&&!flight.landed){flight.step(1/120,input,world.colliders);accumulator-=1/120;steps++;}plane.root.position.copyFrom(flight.position);plane.root.rotationQuaternion.copyFrom(flight.q);run.advance(flight.position.z+world.origin.z,dt,{ground:flight.ground,crashed:flight.crashed,landed:flight.landed,speed:flight.speed,stall:flight.spec.stall,agl:flight.surfaceClearance()});traffic.update(dt,flight,run.distance,!flight.ground);if(!flight.crashed&&!flight.landed){const cableHit=checkCables(flight,previous,world.cables);if(cableHit)flight.crash('Power line strike. Watch for cables between the pylons.',cableHit);const encounters=flight.crashed?{}:traffic.check(flight,previous);if(encounters.collision)flight.crash('Collision with '+encounters.collision+'.',encounters.impact);else if(!flight.crashed&&flight.velocity.z>5)for(const event of encounters.passes||[]){run.pass(event);if(event.near)toast('CLOSE PASS +'+money(event.value)+' · '+event.name);}}
  if(!flight.crashed&&!flight.landed){weapons.update(dt,flight,true);pickups.update(dt,flight,previous);}if(flight.crashed){endRun('crashed');}else if(flight.landed){endRun('landed');}else{const state={...flight.controls,flaps:flight.flapsActual,gear:flight.gearActual,gearTarget:flight.gear,speed:flight.speed,ground:flight.ground,throttle:Math.abs(flight.engine),reverse:flight.engine<-.02,boost:flight.boost,velocity:flight.velocity};animateAircraft(plane,dt,state);effects.exhaust(plane,state,dt);if(sonic.update(plane,flight,dt))toast('MACH 1 · SOUND BARRIER BROKEN');audio.update(state,selected,flight.fuel<=0);if(flight.fuel<=0&&!emptyNotified){emptyNotified=true;toast('Engine out. Lower the nose to keep gliding.');}rebase();world.update(flight.position,false,flight.velocity);}}
 else if(mode==='crash'){weapons.update(dt,flight,false);crash.update(dt);traffic.update(dt,flight,run.distance,false);audio.update({throttle:0},selected,true);if(run.tickCinematic(dt))showResults();}
 else if(mode==='landing'){weapons.update(dt,flight,false);flight.velocity.scaleInPlace(Math.exp(-dt*1.7));flight.position.addInPlace(flight.velocity.scale(dt));flight.position.y=Math.max(groundHeight(flight.position.x,flight.position.z),0)+flight.spec.gearHeight;plane.root.position.copyFrom(flight.position);animateAircraft(plane,dt,{...flight.controls,flaps:flight.flapsActual,gear:flight.gearActual,gearTarget:flight.gear,speed:flight.velocity.length(),ground:true,throttle:Math.abs(flight.engine)*Math.exp(-run.cinematicTime*3)});audio.update({throttle:0},selected,true);if(run.tickCinematic(dt))showResults();}
 else if(flight)audio.update({throttle:0},selected,true);if(mode==='results'&&flight)weapons.update(dt,flight,false);if(['crash','landing','results'].includes(mode)&&flight)world.update(flight.position,false,flight.velocity);if(!paused){effects.update(dt);updateCamera(dt);if(mode==='flight')updateHUD(dt);}scene.render();shopPreview?.render(dt);marketPreview?.render(dt);
}
async function init(){try{if(!B)throw Error('The graphics engine could not load. Refresh to try again.');engine=new B.Engine($('world'),true,{stencil:true,powerPreference:'high-performance'});renderBudget=new RenderBudget(devicePixelRatio||1);renderBudget.apply(engine);scene=new B.Scene(engine);scene.clearColor=B.Color4.FromHexString('#aacbd4ff');scene.fogMode=B.Scene.FOGMODE_EXP2;scene.fogDensity=.00065;scene.fogColor=B.Color3.FromHexString('#a9c9cc');initMaterials(scene);const hemi=new B.HemisphericLight('sky fill',V.Up(),scene);hemi.intensity=.84;hemi.groundColor=B.Color3.FromHexString('#7b8271');sun=new B.DirectionalLight('afternoon sun',new V(-.45,-.85,.34),scene);sun.intensity=2.2;sun.diffuse=B.Color3.FromHexString('#fff4d6');sun.shadowMinZ=1;sun.shadowMaxZ=190;sun.autoUpdateExtends=false;sun.orthoLeft=-32;sun.orthoRight=32;sun.orthoTop=32;sun.orthoBottom=-32;shadow=new B.ShadowGenerator(1536,sun);shadow.usePercentageCloserFiltering=true;shadow.filteringQuality=B.ShadowGenerator.QUALITY_MEDIUM;shadow.bias=.0015;shadow.normalBias=.018;shadow.setDarkness(.25);glow=new B.GlowLayer('reactor radiance',scene,{mainTextureFixedSize:512,blurKernelSize:32});glow.intensity=.55;glow.isEnabled=false;camera=new B.FreeCamera('flight camera',new V(0,30,-20),scene);camera.minZ=.09;camera.maxZ=6000;camera.inputs.clear();scene.activeCamera=camera;scene.imageProcessingConfiguration.toneMappingEnabled=true;scene.imageProcessingConfiguration.toneMappingType=B.ImageProcessingConfiguration.TONEMAPPING_ACES;scene.imageProcessingConfiguration.exposure=1.05;scene.imageProcessingConfiguration.contrast=1.06;await new Promise(r=>setTimeout(r,20));world=new EndlessWorld(scene,WORLD_SEED,damage);$('loadText').textContent='Filling the skies with wildlife and aircraft…';await new Promise(r=>setTimeout(r,20));traffic=new Traffic(scene,damage);effects=new VoxelEffects(scene);sonic=new SupersonicEffects(scene,audio);markers=new TrafficMarkers($('trafficMarkers'));pickupMarkers=new TrafficMarkers($('pickupMarkers'));crash=new CrashSequence(scene,effects,world,traffic);weapons=new MissileSystem(scene,world,traffic,effects,audio,event=>{if(mode==='flight'&&run.hit(event))toast('MISSILE HIT +'+money(event.value)+' · '+event.name);});pickups=new AmmoPickups(scene,weapons,effects,count=>toast('MISSILE RELOAD · +'+count+' ROUNDS'));await prepareWorld(18273,V.Zero());buildPlane();plane.root.position.set(0,groundHeight(0,0)+plane.spec.gearHeight,0);bindControls();updateDamageUI();updateCamera(.016,true);window.addEventListener('resize',()=>engine.resize());$('loading').style.display='none';engine.runRenderLoop(render);window.frontier={build:'balance-8',get scene(){return scene},get world(){return world},get plane(){return plane},get flight(){return flight},get run(){return run},get mode(){return mode},progress,damage,sonic,get weapons(){return weapons},get pickups(){return pickups},get rendering(){return renderBudget}};}catch(e){console.error(e);$('loadText').textContent=e.message||'Unable to start WebGL. Enable hardware acceleration and refresh.';$('loading').querySelector('.load-line').style.display='none';}}
init();
